package SolusVM::Client::Specification;
$SolusVM::Client::Specification::VERSION = '0.001';
use v5.36;
use warnings FATAL => 'all';
use re '/aa';

use Cpanel::JSON::XS    ();
use File::Path          qw{make_path};
use File::Slurper       ();
use File::Slurper::Temp ();
use File::Spec          ();
use HTTP::Tiny          ();
use Time::Piece         ();

# ABSTRACT: The SolusVM 2 API, distilled out of its OpenAPI document


our $SPEC_URL  = 'https://installer.dev.solusvm.com/admin-docs.json';
our $SPEC_FILE = 'solusvm2.json';

# The methods of an OpenAPI path item that are operations.  Everything else in
# there -- parameters, summary, servers -- describes the path, not a call.
my %IS_OPERATION = map { $_ => 1 } qw{get put post delete patch head options trace};


sub load (%options) {
    state %cache;

    my $key = $options{file} // q{};
    return $cache{$key} if $cache{$key};

    my $json    = defined $options{file} ? File::Slurper::read_binary( $options{file} ) : _baked();
    my $entries = Cpanel::JSON::XS->new->utf8->decode($json);

    my %spec;
    @spec{ map { $_->{name} } @{$entries} } = @{$entries};

    $cache{$key} = \%spec;
    return \%spec;
}


sub distil ($document) {
    my $paths = $document->{paths};
    die "That is not an OpenAPI document: it has no paths.\n" unless ref $paths eq 'HASH';

    my $resolve = _resolver($document);

    my @entries;
    foreach my $uri ( sort keys %{$paths} ) {
        foreach my $method ( sort keys %{ $paths->{$uri} } ) {
            next unless $IS_OPERATION{$method};
            push @entries, _entry( $uri, $method, $paths->{$uri}{$method}, $resolve );
        }
    }

    my %seen;
    foreach my $entry (@entries) {
        my $already = $seen{ $entry->{name} };
        die "$entry->{operation_id} and $already->{operation_id} would both be called $entry->{name}.\n" if $already;
        $seen{ $entry->{name} } = $entry;
    }

    return \@entries;
}

# Path parameters come out of the URI rather than out of the operation's
# parameter list, because the document does not always declare them: GET
# /servers/{id} names no parameters at all.  The URI is the one place a
# placeholder is guaranteed to appear, since appearing is what it is for.
sub _entry ( $uri, $method, $operation, $resolve ) {
    my $id = $operation->{operationId};
    die "$method $uri has no operationId, so there is nothing to name it after.\n" unless defined $id && length $id;

    my @path_params  = $uri =~ m/[{](\w+)[}]/g;
    my @query_params = map { $_->{name} } grep { ( $_->{in} // q{} ) eq 'query' } @{ $operation->{parameters} // [] };

    my $schema = $resolve->( $operation->{requestBody} )->{content}{'application/json'}{schema};
    $schema = $resolve->($schema);

    return {
        name         => operation_name( $id, uc $method, $uri ),
        operation_id => $id,
        method       => uc $method,
        uri          => $uri,
        path_params  => \@path_params,
        query_params => \@query_params,
        body_params  => [ sort keys %{ $schema->{properties} // {} } ],
        required     => [ sort @{ $schema->{required}        // [] } ],
        has_body     => ( $operation->{requestBody} ? 1 : 0 ),
        tag          => ( $operation->{tags} // [] )->[0] // q{},
        summary      => $operation->{summary}             // q{},
    };
}


sub operation_name ( $operation_id, $method = undef, $uri = undef ) {
    my $name = lc $operation_id;
    $name =~ s/[^a-z0-9]+/_/g;
    $name =~ s/^_+|_+$//g;

    return $name                                                                                    unless _is_digest($operation_id) || $name !~ m/^[a-z]/;
    die "$operation_id is no kind of name, and there is no verb and path here to build one from.\n" unless defined $method && defined $uri;

    my @segments = grep { length && index( $_, '{' ) != 0 } split '/', $uri;
    return join '_', lc $method, @segments;
}

# What SolusVM leaves behind when whatever generates their document fails to
# name an operation.  Matching the shape rather than listing the thirteen means
# the fourteenth is handled too.
sub _is_digest ($operation_id) {
    return $operation_id =~ m/^[0-9a-f]{32}$/ ? 1 : 0;
}


sub fetch (%options) {
    my $dir = $options{dir};
    die "fetch needs a directory to write the spec into.\n" unless defined $dir && length $dir;

    my $url  = $options{url} // $SPEC_URL;
    my $file = File::Spec->catfile( $dir, $SPEC_FILE );
    my $ua   = $options{ua} // HTTP::Tiny->new( timeout => 60 );

    my %headers;
    if ( $options{once} ) {
        my @stat = stat $file;
        $headers{'If-Modified-Since'} = Time::Piece->gmtime( $stat[9] )->strftime('%a, %d %b %Y %H:%M:%S GMT') if @stat;
    }

    my $response = $ua->get( $url, { headers => \%headers } );
    return undef if $response->{status} == 304;
    die "Could not fetch the SolusVM API spec from $url: $response->{status} $response->{reason}\n" unless $response->{success};

    my $entries = distil( Cpanel::JSON::XS->new->utf8->decode( $response->{content} ) );

    make_path($dir) unless -d $dir;
    File::Slurper::Temp::write_binary( $file, Cpanel::JSON::XS->new->utf8->canonical->encode($entries) );

    return $file;
}

# OpenAPI lets any node be a reference to one somewhere else in the document,
# and SolusVM uses that for the bodies that several operations share.  Following
# one is the difference between knowing what a call takes and knowing only that
# it takes something.
sub _resolver ($document) {
    my $follow;
    $follow = sub ( $node, $depth = 0 ) {
        return {}    unless ref $node eq 'HASH';
        return $node unless defined $node->{'$ref'};
        die "A \$ref in this document points at itself, or close enough: $node->{'$ref'}\n" if $depth > 10;

        my $target = $document;
        foreach my $step ( split '/', $node->{'$ref'} ) {
            next if $step eq '#' || !length $step;
            $target = $target->{$step};
            return {} unless ref $target eq 'HASH';
        }

        return $follow->( $target, $depth + 1 );
    };

    return $follow;
}

# Slurped once and kept, because there is only one pass through a filehandle.
sub _baked {
    state $baked;
    $baked //= do { local $/ = undef; <DATA> };
    return $baked;
}

1;

=pod

=encoding UTF-8

=head1 NAME

SolusVM::Client::Specification - The SolusVM 2 API, distilled out of its OpenAPI document

=head1 VERSION

version 0.001

=head1 SYNOPSIS

    my $spec = SolusVM::Client::Specification::load();

    print $spec->{get_list_of_servers}{method}, "\n";    # GET
    print $spec->{get_list_of_servers}{uri},    "\n";    # /servers

=head1 DESCRIPTION

SolusVM publishes an OpenAPI 3.0 document describing the 309 operations of its
version 2 API.  This module carries a distillation of it -- everything
L<SolusVM::Client> needs in order to turn an operation into an HTTP request, and
nothing else -- so that a client can be built out of the vendor's own description
of the API rather than out of a hand-written list that goes stale.

The distillation is baked into this file, so nothing reaches the network at
runtime.  L</fetch> is how it gets regenerated when SolusVM ships new endpoints.

=head1 FUNCTIONS

=head2 load

Returns the spec as a hashref keyed on operation name, each value a hashref of:

=over 4

=item * C<name> -- the perl method name, as L</operation_name> derived it

=item * C<operation_id> -- the C<operationId> it came from, to find the operation in the published reference

=item * C<method> -- the HTTP verb, upper case

=item * C<uri> -- the path below the API prefix, C<{id}> placeholders and all

=item * C<path_params> -- the placeholder names in C<uri>, in the order they appear

=item * C<query_params> -- the query parameter names the operation declares

=item * C<body_params> -- the body property names it declares, and C<required> the subset it insists on

=item * C<has_body> -- whether the operation takes a request body

=item * C<tag>, C<summary> -- the grouping and the one-line description, for L<SolusVM::Client/catalog>

=back

Takes an optional C<< file => $path >> naming a distilled spec written by
L</fetch>, for running against an API newer than this release.

The result is memoised for the life of the process, keyed on that path.  A spec
file that changes underneath a running program is not a case worth serving; call
it again with a different path to get a different spec.

=head2 distil

Takes the decoded OpenAPI document and returns the arrayref of entries described
in L</load>.  Kept apart from L</fetch> so that what the client believes about an
API can be tested against a document without fetching one.

=head2 operation_name

Turns an C<operationId> into a perl method name: lower cased, with every run of
characters that cannot appear in an identifier collapsed to a single underscore.

The result is clumsy -- C<create_a_new_server>, C<get_an_existing_api_token> --
and deliberately so.  It derives in both directions, so a name in your code can
be found in SolusVM's published reference by eye, and an operation added to a
future spec arrives named without anybody having to decide anything.

Thirteen operations have no name to derive one from.  SolusVM's document gives
them a 32 character hex digest where the C<operationId> should be -- the whole of
C<License>, C<Search>, C<Usage> and C<Server Batch Actions> -- and one of those
digests begins with a digit, which perl will not accept as a method name at all.
For those the name is built out of the verb and the path instead, so
C<POST /servers/start> becomes C<post_servers_start>.  Pass C<$method> and C<$uri>
so that it can be.

=head2 fetch

Downloads the OpenAPI document, distils it, and writes the result as JSON into
C<< dir => $dir >> as F<solusvm2.json>.  Returns the path it wrote, or undef when
there was nothing to do.

Options are C<dir> (required), C<url> (defaulting to
C<$SolusVM::Client::Specification::SPEC_URL>), C<once> to skip the download when
the file is already there and the server reports nothing newer, and C<ua> to hand
it your own L<HTTP::Tiny>.

This is on no runtime path.  It exists to regenerate the baked-in spec, and to
let somebody run against an API newer than this release without waiting for one:

    perl -MSolusVM::Client::Specification -e 'SolusVM::Client::Specification::fetch( dir => "." )'

The URL it defaults to is the one the published reference at
L<https://docs.solusvm.com/en/solusvm2/api-reference/api/> loads its document
from, and it lives on a vendor development host.  Expect to need C<url> one day.

=head1 SEE ALSO

Please see those modules/websites for more information related to this module.

=over 4

=item *

L<SolusVM::Client|SolusVM::Client>

=back

